const 驱动页B64 = "";
const 驱动页 = new TextDecoder().decode(Uint8Array.from(atob(驱动页B64), c => c.charCodeAt(0)));
const 工具页B64 = "";
const 工具页 = new TextDecoder().decode(Uint8Array.from(atob(工具页B64), c => c.charCodeAt(0)));

const 白名单 = new Set([
  "aqtw.qq.com",
  "api.steampowered.com",
  "store.steampowered.com",
  "servers-frontend.fivem.net",
]);

const 跨域 = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET,OPTIONS",
  "Access-Control-Allow-Headers": "*",
  "Cache-Control": "public, max-age=60",
};

Deno.serve(async (请求) => {
  if (请求.method === "OPTIONS") {
    return new Response(null, { headers: 跨域 });
  }

  const 地址 = new URL(请求.url);
  if (地址.pathname === "/toolbox") {
    return new Response(工具页, {
      headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "public, max-age=600" },
    });
  }

  if (地址.pathname === "/drive") {
    return new Response(驱动页, {
      headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "public, max-age=600" },
    });
  }

  if (地址.pathname === "/api-proxy") {
    if (请求.method === "OPTIONS") return new Response(null, { headers: 跨域 });
    const 目标 = 地址.searchParams.get("url");
    if (!目标) return new Response('{"error":"缺少 url"}', { status: 400, headers: 跨域 });
    let 址: URL;
    try { 址 = new URL(目标); } catch { return new Response('{"error":"地址不合法"}', { status: 400, headers: 跨域 }); }
    const 名单 = ["api.openai.com","api.anthropic.com","api.deepseek.com","generativelanguage.googleapis.com","openrouter.ai"];
    if (!名单.includes(址.hostname)) return new Response('{"error":"域名不在白名单"}', { status: 403, headers: 跨域 });
    const 转发头 = new Headers();
    for (const k of ["authorization","x-api-key","anthropic-version","anthropic-dangerous-direct-browser-access","content-type"]) {
      const v = 请求.headers.get(k); if (v) 转发头.set(k, v);
    }
    const 体 = (请求.method === "GET" || 请求.method === "HEAD") ? undefined : await 请求.arrayBuffer();
    const 回 = await fetch(址.toString(), { method: 请求.method, headers: 转发头, body: 体 });
    const 新头 = new Headers(回.headers);
    for (const [键, 值] of Object.entries(跨域)) 新头.set(键, 值);
    return new Response(回.body, { status: 回.status, headers: 新头 });
  }

  if (地址.pathname === "/health") {
    return new Response(JSON.stringify({ ok: true }), {
      headers: { ...跨域, "Content-Type": "application/json; charset=utf-8" },
    });
  }

  const 目标 = 地址.searchParams.get("url");
  if (!目标) {
    return new Response(JSON.stringify({ error: "缺少 url 参数" }), {
      status: 400,
      headers: { ...跨域, "Content-Type": "application/json; charset=utf-8" },
    });
  }

  let 网址: URL;
  try {
    网址 = new URL(目标);
  } catch {
    return new Response(JSON.stringify({ error: "地址不合法" }), {
      status: 400,
      headers: { ...跨域, "Content-Type": "application/json; charset=utf-8" },
    });
  }

  if (!白名单.has(网址.hostname)) {
    return new Response(JSON.stringify({ error: "域名不在白名单" }), {
      status: 403,
      headers: { ...跨域, "Content-Type": "application/json; charset=utf-8" },
    });
  }

  try {
    const 回应 = await fetch(网址.toString(), {
      headers: {
        "User-Agent": "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X)",
        "Accept": "application/json,*/*",
      },
      redirect: "follow",
    });

    const 文本 = await 回应.text();
    return new Response(文本, {
      status: 200,
      headers: { ...跨域, "Content-Type": "application/json; charset=utf-8" },
    });
  } catch (错) {
    return new Response(JSON.stringify({ error: String(错) }), {
      status: 502,
      headers: { ...跨域, "Content-Type": "application/json; charset=utf-8" },
    });
  }
});
